mapper.select:
select id,res_name as name,url,is_leaf as leafTag,permission as code,pid,seq_no as seqNo,assign_type as assignType from (select a.*,0 as assign_type from t_sys_resource_info a,t_sys_resource_role_r b,t_sys_role_info c,t_sys_user_role_r d where a.status='1' and b.status='1' and a.ID=b.RES_ID and b.role_id=c.id and c.id=d.role_id and d.user_id=@userId and a.STATUS='1' and b.status='1' 

	var sqlstr='';
	if(tenantId!=null){
		sqlstr=' and ((a.tenant_id=@tenantId and d.tenant_id=@tenantId) or (a.tenant_id=0 and b.tenant_id=0 and c.tenant_id=0))'
	}
	sqlstr

union
select c.*,d.assign_type from t_sys_resource_info c,t_sys_resource_user_r d where c.id=d.res_id and d.USER_ID=@userId and c.STATUS=1)e order by res_code,seq_no,assign_type desc
